package com.nimbusbill.customer.entity;
import jakarta.persistence.*; import java.math.BigDecimal; import java.util.*;
@Entity @Table(name="pricing_rules") public class PricingRule{
 @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; @ManyToOne(optional=false) @JoinColumn(name="version_id") private PricingPlanVersion version; @ManyToOne(optional=false) @JoinColumn(name="product_id") private PaymentProduct product; @Enumerated(EnumType.STRING) @Column(name="charge_type",nullable=false,length=20) private PricingUnit chargeType; @Column(name="fixed_fee",precision=19,scale=4) private BigDecimal fixedFee; @Column(name="percentage_rate",precision=12,scale=6) private BigDecimal percentageRate; @Column(name="minimum_fee",precision=19,scale=4) private BigDecimal minimumFee; @Column(name="maximum_fee",precision=19,scale=4) private BigDecimal maximumFee; @Column(name="tax_rate",nullable=false,precision=8,scale=4) private BigDecimal taxRate=BigDecimal.ZERO; @Column(nullable=false) private int priority=100; @OneToMany(mappedBy="rule",cascade=CascadeType.ALL,orphanRemoval=true) @OrderBy("sequenceNo ASC") private List<PricingSlab> slabs=new ArrayList<>();
 public UUID getId(){return id;} public PricingPlanVersion getVersion(){return version;} public void setVersion(PricingPlanVersion v){version=v;} public PaymentProduct getProduct(){return product;} public void setProduct(PaymentProduct v){product=v;} public PricingUnit getChargeType(){return chargeType;} public void setChargeType(PricingUnit v){chargeType=v;} public BigDecimal getFixedFee(){return fixedFee;} public void setFixedFee(BigDecimal v){fixedFee=v;} public BigDecimal getPercentageRate(){return percentageRate;} public void setPercentageRate(BigDecimal v){percentageRate=v;} public BigDecimal getMinimumFee(){return minimumFee;} public void setMinimumFee(BigDecimal v){minimumFee=v;} public BigDecimal getMaximumFee(){return maximumFee;} public void setMaximumFee(BigDecimal v){maximumFee=v;} public BigDecimal getTaxRate(){return taxRate;} public void setTaxRate(BigDecimal v){taxRate=v;} public int getPriority(){return priority;} public void setPriority(int v){priority=v;} public List<PricingSlab> getSlabs(){return slabs;}
}
